cd /workspace && node -e "
const { createClient } = require('@supabase/supabase-js');
const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

async function check() {
  // Check what start_times look like
  const { data: khEvents } = await supabase
    .from('events')
    .select('id, title_en, start_time')
    .eq('source', 'kulturhuset');

  console.log('Kulturhuset start_times:');
  khEvents?.forEach(e => console.log(' ', e.start_time));

  // Check with a simple query
  const now = new Date().toISOString();
  console.log('\\nCurrent UTC time:', now);

  const { data: futureEvents } = await supabase
    .from('events')
    .select('id, title_en, start_time')
    .eq('source', 'kulturhuset')
    .gte('start_time', now);

  console.log('\\nKulturhuset events gte now:');
  futureEvents?.forEach(e => console.log(' ', e.start_time));
  console.log('Count:', futureEvents?.length || 0);
}

check().catch(console.error);
